INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64093785', 64093785, 'analyze_legacy', 'Kementerian Dalam Negeri', 'central', 'DIREKTORAT JENDERAL BINA ADMINISTRASI KEWILAYAHAN', 'Asisten Tenaga Ahli Evaluasi dan Analisis Pelaksanaan Tugas dan Wewenang Gubernur Sebagai Wakil Pemerintah Pusat', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 62931000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', '1. Membantu menyusun instrumen analisis dan evaluasi, seperti indikator kinerja, matriks penilaian, dan checklist kepatuhan regulasi. 2. Melakukan analisis awal (preliminary analysis) terhadap capaian, hambatan, dan kesenjangan pelaksanaan tugas GWPP. 3. Mengidentifikasi permasalahan utama dalam pelaksanaan pembinaan dan pengawasan gubernur terhadap kabupaten/kota. 4. Membantu membandingkan antara ketentuan normatif (regulasi) dan implementasi di lapangan.', '1. Mendukung pelaksanaan monitoring kegiatan pembinaan, pengawasan, dan koordinasi gubernur sebagai GWPP. 2. Mendokumentasikan hasil rapat, forum koordinasi, dan kegiatan lapangan yang berkaitan dengan fungsi GWPP. 3. Menyusun notulensi, laporan kunjungan kerja, dan rekap hasil supervisi.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1336661);
